	size_t len;
	struct stat buf;
	unsigned int i;

	if (check_path(path))
		return -1;

	// Trim trailing '/' should they exist
	len = strlen(path);
	if (len > 2 && path[len-1] == '/') {
		while (path[len-1] == '/' && len > 1) {
			path[len-1] = 0;
			len--;
		}
	}
	if (stat(path, &buf) == 0) {
		if (S_ISDIR(buf.st_mode))
			type = AUDIT_DIR;
	}
	/* Ensure the rule is empty before adding a watch */
	if ((*rulep)->field_count || (*rulep)->action || (*rulep)->flags ||
	    (*rulep)->buflen)
