+	struct field_compare *compares;
+	size_t compare_count;
+	size_t compare_alloc;
+	char **syscalls;
+	size_t syscall_count;
+	size_t syscall_alloc;
+	char **keys;
+	size_t key_count;
+	size_t key_alloc;
+	char *path;
+	char *perm;
+	bool explicit_all;
+	bool all;
+	bool has_perm;
+	bool removed;
+	bool has_error;
